<?php require 'header.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['category_name']??'');$brand=$_POST['brand']??'';if($name&&in_array($brand,['Samsung','Apple'],true)){db()->prepare('INSERT INTO categories(category_name,brand) VALUES(?,?)')->execute([$name,$brand]);flash('success','Category added.');}header('Location: manage-categories.php');exit;}$categories=db()->query('SELECT c.*,COUNT(p.id) products FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.brand,c.category_name')->fetchAll();?><div class="admin-title"><p>CATALOGUE</p><h2>Manage categories</h2></div><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input required name="category_name" placeholder="e.g. Galaxy Ultra Series"><select name="brand"><option>Samsung</option><option>Apple</option></select><button class="save">Add category</button></form><section class="admin-panel"><table><thead><tr><th>Category</th><th>Brand</th><th>Products</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?=e($c['category_name'])?></td><td><?=e($c['brand'])?></td><td><?=$c['products']?></td></tr><?php endforeach?></tbody></table></section><?php require 'footer.php'; ?>
